import { normalizePath } from "./shared";

const DOC_FR_TRACE_RE = /\bFR-L1-(\d+)(?:(?:[〜～]|\.\.)(?:FR-L1-)?(\d+)|((?:\/\d+)+))?/g;
const U_FR_TRACE_RE = /\bU-FR-L1-(\d+)(?:(?:[〜～]|\.\.)(?:U-FR-L1-)?(\d+))?/g;
const EXPLICIT_IMPLEMENTATION_TRACE_RE = /@helix-trace\s+(FR-L1-\d+)/g;
const ACTIVE_STATUSES = new Set<ArtifactStatus>(["active"]);
const IMPL_ROLES = new Set<ArtifactRole>(["source", "test"]);
const OPEN_DEFER_LAYERS = new Set<Layer>(["L4", "L5", "L6", "L8"]);

export function analyzeGateConfirm(input: GateConfirmDocs): GateConfirmResult {
  const statuses = parseGateStatuses(input.gateText);
  if (statuses.length === 0) return { violations: [], skipped: true, ok: false };
  const byGate = new Map(statuses.map((s) => [s.gate, s]));
  const violations: GateConfirmResult["violations"] = [];
  for (const doc of input.docs) {
    if (doc.status !== "confirmed") continue;
    const gate = layerToGate(doc.layer);
    if (!gate) continue;
    const gateStatus = byGate.get(gate);
    if (!gateStatus) continue;
    if (!gateStatus.pass) {
      violations.push({ file: doc.file, layer: doc.layer, gate, gateStatus: gateStatus.status });
    }
  }
  return { violations, skipped: false, ok: violations.length === 0 };

const passed = Boolean(input.humanApproved);
const messages =
  input.reviewKind && input.reviewKind !== "human"
    ? ["standalone judgment gate requires human review evidence"]
    : [];
return {
  gate: input.gate,
  mode: input.mode,
  passed: passed && messages.length === 0,
  review_kind: "human",
  cross_agent_review: "unavailable",
  messages:
    messages.length > 0
      ? messages
      : passed
        ? ["standalone human approval ok"]
        : ["standalone judgment gate requires human approval"],
};

function validateTemplate(template: WorkflowTemplate | null): string[] {
  if (!template) return ["no template selected"];
  const errors: string[] = [];
  if (template.allowed_tools.length === 0) errors.push("allowed tools are required");
  if (template.transitions.length === 0) errors.push("transitions are required");
  if (template.exit_criteria.length === 0) errors.push("exit criteria are required");
  return errors;

function isActiveStatus(status: string): boolean {
  return ["draft", "active", "confirmed"].includes(status.toLowerCase());
}

export function buildChangePackageDeltaArchiveReport(
  manifest: ChangePackageManifest,
  options: { sourceCommand?: string } = {},
): ChangePackageDeltaArchiveReport {
  const findings: ChangePackageDeltaArchiveReport["findings"] = [];
  const designCount = (manifest.design_paths ?? []).length;
  const testDesignCount = (manifest.test_design_paths ?? []).length;
  const archiveDecision = manifest.archive_decision ?? {};
  const rollbackPath = archiveDecision.rollback_path ?? null;
  const evidenceDigest = archiveDecision.evidence_digest ?? null;

  if (manifest.archive_requested && isActiveStatus(String(manifest.plan_status))) {
    if (designCount === 0 && testDesignCount === 0) {
      findings.push({
        code: "archive_without_design_or_test_delta",
        severity: "error",
        detail: `${manifest.plan_id} archive request has no design/test-design delta binding`,
      });

if (manifest.archive_requested && isActiveStatus(String(manifest.plan_status))) {
  if (designCount === 0 && testDesignCount === 0) {
    findings.push({
      code: "archive_without_design_or_test_delta",
      severity: "error",
      detail: `${manifest.plan_id} archive request has no design/test-design delta binding`,
    });
  }
  if (!present(rollbackPath) || !present(evidenceDigest)) {
    findings.push({
      code: "archive_decision_missing_rollback_or_digest",
      severity: "error",
      detail: `${manifest.plan_id} archive decision requires rollback path and evidence digest`,
    });
  }

for (const doc of input.docs) {
  if (doc.status !== "confirmed") continue;
  const gate = layerToGate(doc.layer);
  if (!gate) continue;
  const gateStatus = byGate.get(gate);
  if (!gateStatus) continue;
  if (!gateStatus.pass) {
    violations.push({ file: doc.file, layer: doc.layer, gate, gateStatus: gateStatus.status });
  }
}
return { violations, skipped: false, ok: violations.length === 0 };

/**
 * DoD を全消化 (checked≥1 かつ unchecked=0) なのに status が非終端の PLAN を violation として返す。
 */
export function analyzePlanCompletionDrift(plans: PlanCompletionRow[]): PlanCompletionDriftResult {
  const violations = plans
    .filter((p) => p.checkedItems > 0 && p.uncheckedItems === 0 && !isTerminalPlanStatus(p.status))
    .map((p) => ({ planId: p.planId, status: p.status, checkedItems: p.checkedItems }))
    .sort((a, b) => a.planId.localeCompare(b.planId));
  return { violations, ok: violations.length === 0 };

export function loadPlanCompletionDriftInput(repoRoot: string): PlanCompletionRow[] {
  let reviewPlans: ReturnType<typeof loadReviewPlans>;
  try {
    reviewPlans = loadReviewPlans(repoRoot);
  } catch {
    return []; // docs/plans 不在は空 (fail-open、他 lint と同方針)
  }
  const plansDir = join(repoRoot, "docs", "plans");
  const rows: PlanCompletionRow[] = [];
  for (const rp of reviewPlans) {
    if (rp.status === "archived") continue;
    let content = "";
    try {
      content = readFileSync(join(plansDir, rp.file), "utf8");
    } catch {
      continue;
    }
    const { checked, unchecked } = dodChecklistState(content);
    rows.push({
      planId: rp.plan_id,
      status: rp.status,
      checkedItems: checked,
      uncheckedItems: unchecked,
    });
  }
  return rows;

export const TERMINAL_PLAN_STATUSES: ReadonlySet<string> = new Set([
  "confirmed",
  "completed",
  "accepted",
]);

export function normalizedPlanStatus(status: string): string {
  return status.trim().toLowerCase();
}

export function isTerminalPlanStatus(status: string): boolean {
  return TERMINAL_PLAN_STATUSES.has(normalizedPlanStatus(status));
}

/**
 * DoD 全消化済なのに status 非終端の PLAN を surface (PLAN-L7-93、hard fail)。完了 bookkeeping drift
 * (作業完了 + gated downstream confirmed なのに recovery/poc PLAN 自身が draft 放置) → ok=false。
 * I/O 失敗も violation にして fail-close する。
 */
export function checkPlanCompletionDrift(repoRoot: string): {
  messages: string[];
  ok: boolean;
} {
  if (!existsSync(repoRoot)) {
    return {
      messages: ["plan-completion-drift - violation: repo root could not be read"],
      ok: false,
    };
  }
  try {
    const r = analyzePlanCompletionDrift(loadPlanCompletionDriftInput(repoRoot));
    return { messages: planCompletionDriftMessages(r), ok: r.ok };
  } catch {
    return {
      messages: ["plan-completion-drift - violation: PLAN could not be read"],
      ok: false,
    };
  }
}

/**
 * merged-plan-status hard gate (PO 指摘 2026-06-15): generated src が merge 済みなのに owning PLAN が
 * draft / 未 confirm のまま放置される V-model state 不整合を fail-close 検出する。review-evidence gate が
 * confirmed PLAN にのみ証跡を要求し draft を素通りさせる absence-blindness を補完する (柱3 = state DB が
 * フィードバック機構)。
 */
export function checkMergedPlanStatus(repoRoot: string): {
  messages: string[];
  ok: boolean;
} {
  if (!existsSync(repoRoot)) {
    return {
      messages: ["merged-plan-status - violation: repo root could not be read"],
      ok: false,
    };
  }
  try {
    const r = analyzeMergedPlanStatus(loadMergedPlanStatusInput(repoRoot));
    return { messages: mergedPlanStatusMessages(r), ok: r.ok };
  } catch {
    return {
      messages: ["merged-plan-status - violation: PLAN generates could not be read"],
      ok: false,
    };
  }
}

export function checkRecoveryRunwayBinding(
  repoRoot: string,
  prebuiltDb?: HarnessDb,
): { messages: string[]; ok: boolean } {
  if (!existsSync(repoRoot)) {
    return {
      messages: ["recovery-runway-binding - violation: repo root could not be read"],
      ok: false,
    };
  }
  try {
    const db = prebuiltDb ?? openHarnessDb(":memory:", { repoRoot });
    try {
      if (!prebuiltDb) rebuildHarnessDb({ repoRoot, db });
      const snapshot = buildDoctorCurrentLocationSnapshot(repoRoot, db);
      const zipManifest = analyzeVmodelZipManifest(repoRoot);
      const fit = buildVmodelFitReport(snapshot, zipManifest, { repoRoot });
      const runway = fit.recovery_runway_gate;
      const violations: string[] = [];
      const blocking = runway.current_blocking_count;
      const phaseSequences = runway.phases.map((phase) => phase.sequence);
      if (blocking > 0 && runway.phases.length === 0) {
        violations.push("phases=empty");
      }
      if (runway.required_phase_count !== runway.phases.length) {
        violations.push(
          `required_phase_count=${runway.required_phase_count}/${runway.phases.length}`,
        );
      }
      if (blocking > 0 && !runway.next_phase_action) {
        violations.push("next_phase_action=missing");
      }
      if (blocking > 0 && runway.next_command.length === 0) {
        violations.push("next_command=missing");
      }
      if (blocking > 0 && runway.next_execution_command.length === 0) {
        violations.push("next_execution_command=missing");
      }
      if (
        runway.machine_actionable_count > 0 &&
        (!runway.next_machine_command ||
          !runway.next_machine_probe_command ||
          !runway.next_machine_materialize_command)
      ) {
        violations.push("machine_lane_commands=missing");
      }
      for (const [index, sequence] of phaseSequences.entries()) {
        if (sequence !== index + 1) violations.push(`phase_sequence=${phaseSequences.join(",")}`);
      }
      for (const phase of runway.phases) {
        if (phase.count <= 0)
          violations.push(`${phase.sequence}.${phase.action}.count=${phase.count}`);
        if (phase.remaining_after_phase < 0) {
          violations.push(
            `${phase.sequence}.${phase.action}.remaining=${phase.remaining_after_phase}`,
          );
        }
        if (phase.command.length === 0) {
          violations.push(`${phase.sequence}.${phase.action}.command=missing`);
        }
        if (phase.postcheck_commands.length === 0) {
          violations.push(`${phase.sequence}.${phase.action}.postcheck=missing`);
        }
        if (
          phase.phase_type === "machine" &&
          (!phase.evidence_probe_command ||
            !phase.evidence_materialize_command ||
            !phase.evidence_approval_draft_command ||
            !phase.evidence_apply_dry_run_command)
        ) {
          violations.push(`${phase.sequence}.${phase.action}.machine_evidence_commands=missing`);
        }
        if (phase.phase_type === "approval" && !phase.human_required) {
          violations.push(`${phase.sequence}.${phase.action}.approval_human_required=false`);
        }
        if (phase.phase_type === "design" && phase.human_required) {
          violations.push(`${phase.sequence}.${phase.action}.design_human_required=true`);
        }
      }
      const phaseSummary = runway.phases
        .map(
          (phase) =>
            `${phase.sequence}:${phase.phase_type}:${phase.action}:${phase.count}:remaining=${phase.remaining_after_phase}:next=${phase.next_gate}`,
        )
        .join(",");
      const commandSummary = [
        `next=${runway.next_command}`,
        `execute=${runway.next_execution_command}`,
        `machine=${runway.next_machine_command ?? "-"}`,
        `probe=${runway.next_machine_probe_command ?? "-"}`,
        `materialize=${runway.next_machine_materialize_command ?? "-"}`,
        `approval_draft=${runway.next_machine_approval_draft_command ?? "-"}`,
        `apply_dry_run=${runway.next_machine_apply_dry_run_command ?? "-"}`,
      ].join(" ");
      const prefix =
        violations.length === 0
          ? "recovery-runway-binding - OK"
          : "recovery-runway-binding - violation";
      return {
        ok: violations.length === 0,
        messages: [
          `${prefix}: status=${runway.status} blocking=${runway.current_blocking_count} machine=${runway.machine_actionable_count} approval=${runway.human_approval_count} reverse=${runway.design_reverse_count} after_machine=${runway.remaining_after_machine_lanes} phases=${runway.required_phase_count} next=${runway.next_phase_action ?? "-"} phase=${runway.next_phase_type ?? "-"} gate=${runway.next_gate} command=${runway.command}`,
          `recovery-runway-binding - commands: ${commandSummary}`,
          `recovery-runway-binding - phases: ${phaseSummary || "none"}`,
          ...violations.map((violation) => `recovery-runway-binding - violation: ${violation}`),
        ],
      };
    } finally {
      if (!prebuiltDb) db.close();
    }
  } catch {
    return {
      messages: ["recovery-runway-binding - violation: recovery runway projection could not run"],
      ok: false,
    };
  }
}

export function checkRecoveryExitBinding(
  repoRoot: string,
  prebuiltDb?: HarnessDb,
): { messages: string[]; ok: boolean } {
  if (!existsSync(repoRoot)) {
    return {
      messages: ["recovery-exit-binding - violation: repo root could not be read"],
      ok: false,
    };
  }
  try {
    const db = prebuiltDb ?? openHarnessDb(":memory:", { repoRoot });
    try {
      if (!prebuiltDb) rebuildHarnessDb({ repoRoot, db });
      const snapshot = buildDoctorCurrentLocationSnapshot(repoRoot, db);
      const recoveryPlan = buildProjectRecoveryPlan(snapshot, { limit: 0 });
      const exit = recoveryPlan.exit_forecast;
      const reentry = recoveryPlan.reentry_forecast;
      const violations: string[] = [];
      const laneTotal = exit.lanes
        .filter((lane) => lane.blocking)
        .reduce((sum, lane) => sum + lane.count, 0);
      if (exit.remaining_queue_items !== laneTotal) {
        violations.push(`remaining_queue_items=${exit.remaining_queue_items}/${laneTotal}`);
      }
      if (exit.remaining_queue_items > 0 && exit.blocking_lanes.length === 0) {
        violations.push("blocking_lanes=empty");
      }
      if (exit.remaining_queue_items > 0 && exit.next_command.length === 0) {
        violations.push("next_command=missing");
      }
      if (recoveryPlan.status === "active" && !recoveryPlan.selected_closure_action) {
        violations.push("selected_closure_action=missing");
      }
      const selectedLane = exit.lanes.find(
        (lane) => lane.action === recoveryPlan.selected_closure_action,
      );
      if (recoveryPlan.selected_closure_action && !selectedLane) {
        violations.push(`selected_lane=${recoveryPlan.selected_closure_action}:missing`);
      }
      if (selectedLane && exit.next_command !== selectedLane.command) {
        violations.push(`next_command=${exit.next_command}/${selectedLane.command}`);
      }
      for (const lane of exit.lanes) {
        if (lane.blocking && lane.count <= 0) {
          violations.push(`${lane.action}.count=${lane.count}`);
        }
        if (lane.blocking && lane.command.length === 0) {
          violations.push(`${lane.action}.command=missing`);
        }
        if (lane.blocking && lane.required_action.length === 0) {
          violations.push(`${lane.action}.required_action=missing`);
        }
        if (lane.action === "close_ready" && lane.count > 0 && !lane.human_required) {
          violations.push("close_ready.human_required=false");
        }
        if (
          (lane.action === "collect_evidence" || lane.action === "repair_failed_evidence") &&
          lane.human_required
        ) {
          violations.push(`${lane.action}.human_required=true`);
        }
      }
      const requiredRecomputeCommands = [
        "helix current-location --json",
        "helix drive model --json",
        "helix roadmap current --json",
        "helix vmodel fit",
      ];
      for (const command of requiredRecomputeCommands) {
        if (!reentry.recompute_commands.includes(command)) {
          violations.push(`missing_recompute=${command}`);
        }
      }
      if (reentry.current_blocking_count !== exit.remaining_queue_items) {
        violations.push(
          `reentry_blocking=${reentry.current_blocking_count}/${exit.remaining_queue_items}`,
        );
      }
      const laneSummary = exit.lanes
        .map(
          (lane) =>
            `${lane.action}:${lane.count}:blocking=${lane.blocking}:human=${lane.human_required}`,
        )
        .join(",");
      const prefix =
        violations.length === 0
          ? "recovery-exit-binding - OK"
          : "recovery-exit-binding - violation";
      return {
        ok: violations.length === 0,
        messages: [
          `${prefix}: status=${exit.status} remaining=${exit.remaining_queue_items} selected=${recoveryPlan.selected_closure_action ?? "-"} next=${exit.next_command} reentry=${reentry.status} after_machine=${reentry.blocking_after_machine_lanes} phases=${reentry.required_phase_count}`,
          `recovery-exit-binding - lanes=${laneSummary || "none"}`,
          `recovery-exit-binding - recompute=${reentry.recompute_commands.join(" && ") || "-"}`,
          ...violations.map((violation) => `recovery-exit-binding - violation: ${violation}`),
        ],
      };
    } finally {
      if (!prebuiltDb) db.close();
    }
  } catch {
    return {
      messages: ["recovery-exit-binding - violation: recovery exit projection could not run"],
      ok: false,
    };
  }
}

export function checkGateConfirm(repoRoot: string): {
  messages: string[];
  ok: boolean;
} {
  if (!existsSync(repoRoot)) {
    return {
      messages: ["gate-confirm - violation: repo root could not be read"],
      ok: false,
    };
  }
  try {
    const r = analyzeGateConfirm(loadGateConfirmDocs(repoRoot));
    return { messages: gateConfirmMessages(r), ok: r.ok };
  } catch {
    return {
      messages: ["gate-confirm - violation: gate-design/doc frontmatter could not be read"],
      ok: false,
    };
  }
}

/**
 * L6 readiness は設計中の draft status 自体をCI失敗へ変換しない warn surface とする。
 * V-pair trace / contract substance が成立することはfail-closeで要求し、freeze完了は
 * `ready` として別途表示する。これは設計を先行して起票できる Forward workflow の境界である。
 */
export function checkL6Completion(repoRoot: string): {
  messages: string[];
  ok: boolean;
} {
  if (!canLoadL6CompletionInputs(repoRoot)) {
    return {
      messages: ["l6-completion - violation: L6 completion inputs could not be read"],
      ok: false,
    };
  }
  try {
    const r = analyzeL6Completion(loadL6CompletionInputs(repoRoot));
    return { messages: l6CompletionMessages(r), ok: r.freezeInputReady };
  } catch {
    return {
      messages: ["l6-completion - violation: L6 completion readiness could not be read"],
      ok: false,
    };
  }
}

export function checkL3ProgressionAuthority(repoRoot: string): {
  messages: string[];
  ok: boolean;
} {
  try {
    const findings = verifyL3ProgressionAuthority(repoRoot);
    return findings.length === 0
      ? { messages: ["l3-progression-authority - OK"], ok: true }
      : {
          messages: findings.map(
            (finding) => `l3-progression-authority - violation: ${finding.path} ${finding.reason}`,
          ),
          ok: false,
        };
  } catch {
    return {
      messages: ["l3-progression-authority - violation: reviewed paths could not be read"],
      ok: false,
    };
  }
}

const design = candidate.design_authority ?? null;
const plan = candidate.plan_authority ?? null;
if (design && (design.source_kind !== "confirmed_design" || design.status !== "confirmed"))
  return base("invalid", "design authority is not confirmed", "親設計をconfirmedにする");

const groups = analyzeVerificationGroups(
  docs,
  pair.orphans,
  loadVerificationPlanEvidence(repoRoot),
);
const l0l7 = groups.find((g) => g.id === "L0-L7");

const messages = [
  ...pairFreezeMessages(pair),
  ...(l0l7 ? verificationGroupMessages([l0l7]) : ["g7-static - violation: L0-L7 group missing"]),
  ...implPlanTraceMessages(impl),
  ...oracleTestTraceMessages(oracle),
  ...leftArmCarryLogMessages(carry),
  coverage.message,
];
const passed =
  pair.ok && Boolean(l0l7?.frozen) && impl.ok && oracle.ok && carry.ok && coverage.ok;

const testAuthor = await executePhase("smart_test_author", 0);
if (testAuthor.status !== "passed") {
  return { ok: false, status: "error", finalVerdict: null, steps, transcript, findings };
}

let finalVerdict: PairAgentRunResult["finalVerdict"] = null;
for (let cycle = 1; cycle <= input.plan.maxFixCycles; cycle++) {
  const implementation = await executePhase("light_implementation", cycle);
  if (!["passed", "pending"].includes(implementation.status)) {
    return { ok: false, status: "error", finalVerdict, steps, transcript, findings };
  }

let finalVerdict: PairAgentRunResult["finalVerdict"] = null;
for (let cycle = 1; cycle <= input.plan.maxFixCycles; cycle++) {
  const implementation = await executePhase("light_implementation", cycle);
  if (!["passed", "pending"].includes(implementation.status)) {
    return { ok: false, status: "error", finalVerdict, steps, transcript, findings };
  }
  const review = await executePhase("smart_review", cycle);
  finalVerdict = review.verdict;
  if (review.verdict === "pass") {
    return { ok: true, status: "passed", finalVerdict, steps, transcript, findings };
  }
  if (review.verdict === "error") {
    return { ok: false, status: "error", finalVerdict, steps, transcript, findings };
  }
}

findings.push({
  code: "max-fix-cycles-exhausted",
  severity: "error",
  message: `pair-agent run exhausted maxFixCycles=${input.plan.maxFixCycles} without a passing smart review verdict`,
});
return { ok: false, status: "failed", finalVerdict, steps, transcript, findings };

function openFindingCount(db: HarnessDb, planId: string): number {
  const row = db
    .prepare("SELECT COUNT(*) AS n FROM findings WHERE status = 'open' AND subject_id LIKE ?")
    .get(`%${planId}%`);
  return Number(row?.n ?? 0);

if (openFindings > 0) {
  readyStatus = "blocked";
  blockedReason = `open findings: ${openFindings}`;
}

if (value.unresolved.some((item) => item.blocking)) {
  findings.push({ code: "blocking_unresolved", detail: "blocking unresolved item remains" });
}

if (value.proposed_next_state !== "awaiting_commit_verifier") {
  findings.push({
    code: "commit_verifier_required",
    detail: "proposal cannot advance beyond the commit verifier boundary",
  });

const selected = [
  coreQuestionId,
  ...WORKFLOW_CONDITIONAL_SIGNALS.filter((signal) => value.signals[signal]).map(
    conditionalQuestionId,
  ),
];
const selectedSet = new Set(selected);
const findings: WorkflowInterviewEvaluation["findings"] = [];
const unresolved: WorkflowInterviewUnresolvedItem[] = [];
const admitted = new Set<string>();

for (const answer of value.answers) {
  if (!selectedSet.has(answer.question_id)) {
    findings.push({ code: "non_applicable_answer", path: `answers.${answer.question_id}` });
    continue;

const freezeAllowed =
  findings.length === 0 && unresolved.length === 0 && admitted.size === selected.length;
return {
  ok: findings.length === 0,
  freeze_allowed: freezeAllowed,
  selected_question_ids: selected,
  admitted_question_ids: [...admitted].sort(),
  unresolved_items: unresolved,

if (answer.authority === "unknown") {
  unresolved.push({
    unresolved_id: `authority:${answer.question_id}`,
    kind: "authority_missing",
    code: "answer_authority_missing",
    source_span: answer.source_span,
    question_history: history,
  });
  continue;

const distinct = new Set(
  value.answers
    .filter((candidate) => candidate.question_id === answer.question_id)
    .map((candidate) => candidate.value),
);
if (distinct.size > 1) {
  if (
    !unresolved.some((item) => item.unresolved_id === `contradiction:${answer.question_id}`)
  ) {
    unresolved.push({
      unresolved_id: `contradiction:${answer.question_id}`,
      kind: "contradiction",
      code: "conflicting_answers",
      source_span: answer.source_span,
      question_history: history,
    });
  }
  continue;

for (const questionId of selected) {
  if (!value.answers.some((answer) => answer.question_id === questionId)) {
    unresolved.push({
      unresolved_id: `missing:${questionId}`,
      kind: "ambiguity",
      code: "answer_missing",
      source_span: `source:${value.source.source_id}`,
      question_history: [questionId],
    });
  }

value.ambiguities.forEach((item, index) => {
  unresolved.push({
    unresolved_id: `ambiguity:${index + 1}`,
    kind: "ambiguity",
    code: "source_ambiguity",
    source_span: item.source_span,
    question_history: [item.detail],
  });
});
