export function loadReviewPlans(repoRoot: string = process.cwd()): ParsedReviewPlan[] {
  const plansDir = join(repoRoot, "docs", "plans");
  if (!existsSync(plansDir)) return [];
  const plans: ParsedReviewPlan[] = [];
  for (const f of readdirSync(plansDir)) {
    // PLAN-*.md のみ対象。サブディレクトリ (archive/_template) は readdirSync が拡張子なし
    // エントリで返すため `.md` 判定で除外されるが、念のため `PLAN-` prefix も明示ガードする
    // (archive 等に PLAN-*.md を直接置いた場合の誤 pickup 防止、backfill-pairing と同等の堅牢性)。
    if (!f.endsWith(".md") || !f.startsWith("PLAN-")) continue;
    plans.push(parseReviewPlan(f, readFileSync(join(plansDir, f), "utf8")));
  }
  const terminalL3 = plans.filter(
    (plan): plan is ParsedReviewPlan & { layer: "L3" } =>
      plan.layer === "L3" && STATUS_REVIEW_REQUIRED.has(plan.status),
  );
  const provenance = readGitPlanDateProvenanceBatch(
    repoRoot,
    terminalL3.map((plan) => plan.file),
  );
  for (const plan of terminalL3) {
    plan.gitDateProvenance = provenance.get(plan.file) ?? {
      source: "git",
      error: "history_unavailable",
    };
  }
  return plans;
}

  const parseViolations = (input.parseFailures ?? []).map((failure) => ({
    planId: failure.planId,
    status: "unknown",
    artifacts: [],
    failure_code: failure.failure_code,
  }));
  const planViolations = input.plans
    .filter(
      (p) =>
        (p.invalidModifications?.length ?? 0) > 0 ||
        (!isTerminalPlanStatus(p.status) &&
          p.mergedArtifacts.length > 0 &&
          !isS3VerifiedPocPendingDecision(p)),
    )
    .map((p) => ({
      planId: p.planId,
      status: p.status,
      artifacts: p.mergedArtifacts,
      ...(p.invalidModifications?.length ? { invalidModifications: p.invalidModifications } : {}),
    }));
  const violations = [...parseViolations, ...planViolations].sort((a, b) =>
    a.planId.localeCompare(b.planId),
  );
  return { violations, ok: violations.length === 0 };
}

function isS3VerifiedPocPendingDecision(p: MergedPlanRow): boolean {
  return (
