export function analyzePlaceholderDeps(docs: PlaceholderDepsDoc[]): PlaceholderDepsResult {
  const violations: PlaceholderDepsViolation[] = [];
  let checked = 0;
  let specBackfillWaits = 0;
  let implStateWaits = 0;
  for (const doc of docs) {
    if (!ACTIVE_STATUSES.has(doc.status.toLowerCase())) continue;
    checked += 1;
    const lines = doc.text.split(/\r?\n/);
    for (const [index, line] of lines.entries()) {
      if (/^\s*(?:[-*]\s*)?`?placeholder_deps`?\s*[:=]/i.test(line)) {
        const waitMatch = line.match(/\bwaiting_layer\s*[:=]\s*"?(L\d+)\b/i);
        if (!waitMatch) {
          violations.push({
            path: doc.path,
            line: index + 1,
            detail: "placeholder_deps is missing waiting_layer, so threshold cannot be evaluated",
          });
          continue;
        }
        const layer = waitMatch[1].toUpperCase();
        if (!KNOWN_LAYERS.has(layer)) {
          violations.push({
            path: doc.path,
            line: index + 1,
            detail: `placeholder_deps waiting_layer ${layer} is not in the canonical/compatibility layer registry — typo?`,
          });

