  repassReview.tests_green_at > repassReview.reviewed_at
) {
  addViolation(
    violations,
    plan.plan_id,
    "invalid-event-order",
    "resolution repass > tests_green > review",
    carryId,
  );

if (
  entry.detected_at >= entry.gate_repass.completed_at ||
  (review?.tests_green_at !== undefined &&
    entry.gate_repass.completed_at > review.tests_green_at) ||
  (review !== undefined && entry.gate_repass.completed_at > review.reviewed_at)
) {
  addViolation(violations, plan.plan_id, "invalid-event-order", carryId, carryId);

for (const disposition of REVIEWED_SAFE_DISPOSITIONS) {
  if (!changedSet.has(disposition.path)) continue;
  if (reviewedSafeSource === null) {
    unsupportedSurfaces.push(`${disposition.path}:reviewed_safe_registry_unavailable`);
    continue;
  }
  const absoluteTarget = join(root, disposition.path);
  const liveDigest = existsSync(absoluteTarget)
    ? sha256(readFileSync(absoluteTarget, "utf8"))
    : null;
  findings.push({
    changed_path: disposition.path,
    dependent_path: reviewedSafePath,
    location: `${reviewedSafePath}:${lineOf(reviewedSafeSource, `path: "${disposition.path}"`)}`,
    field: "contentDigest",
    kind: "semantic_review_pin",
    action: "requires_reassessment",
    recorded_value: disposition.contentDigest,
    live_value: liveDigest,
    stale: disposition.contentDigest !== liveDigest,
  });

if (catalog.reviewedDigestState !== "current") {
  findings.push({
    code:
      catalog.reviewedDigestState === "missing"
        ? "reviewed-digest-missing"
        : "reviewed-digest-stale",
    severity: "error",
    message: `design catalog reviewed digest is ${catalog.reviewedDigestState}; independent reassessment is required`,
    nodeId: catalogNode,
    evidencePath: catalog.reviewedDigestAuthorityPath,
